def checkPerfectNumber(num: int) -> bool:
    # 1 is not a perfect number by definition
    if num == 1:
        return False

    sum_divisors = 1  # 1 is a proper divisor of all numbers except 1

    # Check all divisors up to ⌊num**0.5⌋
    i = 2
    while i * i <= num:
        if num % i == 0:
            sum_divisors += i
            if i != num // i:
                sum_divisors += num // i
        i += 1

    return sum_divisors == num
